c=load_corpus()
def loss(ch): return ch['mean_test_ce'] if ch['mean_test_ce'] is not None else ch['mean_test_mse']
def s_orig(ch): return sum(ch['layer_norm'])+(1 if ch['residual'] else 0)
def s_mod(ch):
    n=sum(ch['layer_norm'])
    if not ch['residual'] and ch['depth']>=3 and not ch['layer_norm'][-1]:
        n=min(n,1)  # unnormalized tail undoes earlier LN
    return n+(1 if ch['residual'] else 0)
def s_mod2(ch):
    n=sum(ch['layer_norm'])
    if not ch['residual'] and ch['depth']>=4 and not ch['layer_norm'][-1]:
        n=n-1
    return n+(1 if ch['residual'] else 0)
res=collections.defaultdict(lambda:[0,0,0,0])
for q in c:
    if q['type']!='architecture_only': continue
    if any(ch['model_type']!='mlp' for ch in q['choices']): continue
    fam=q['family']
    for name,f in [('orig',s_orig),('mod',s_mod),('mod2',s_mod2)]:
        best=max(f(ch) for ch in q['choices'])
        top=[ch for ch in q['choices'] if f(ch)==best]
        # tie-break: deeper
        top.sort(key=lambda ch:-ch['depth'])
        hit= top[0]['letter']==q['correct_letter']
        res[(fam,name)][0]+=1; res[(fam,name)][1]+=hit
