def parse(q):
    parts=re.split(r'\n### Choice ([A-Z])\n',q); out={}
    for i in range(1,len(parts),2):
        t=parts[i+1]; d={}
        m=re.search(r'- Optimizer: (\w+)',t); d['opt']=m.group(1) if m else None
        m=re.search(r'- Learning rate: ([\d.e-]+)',t); d['lr']=float(m.group(1)) if m else None
        m=re.search(r'training_steps: (\d+)',t); d['T']=int(m.group(1)) if m else None
        m=re.search(r'- Momentum: ([\d.]+)',t); d['m']=float(m.group(1)) if m else 0
        out[parts[i]]=d
    return out
def delta(o,lr,T,m):
    if o in ('Adam','AdamW','RMSprop'): return lr*T
    if o=='Adagrad': return 2*lr*np.sqrt(T)
    if o=='SGD': return lr*T*0.01/(1-(m or 0))
def fam(t):
    m=re.search(r'Rule family: `(\w+)`',t); return m.group(1) if m else None
def N(t):
    m=re.search(r'total_samples_seen: (\d+)',t); return int(m.group(1)) if m else None
def rule(ds,rf,cap_s=0.16,cap_o=2.2):
    items=sorted(ds.items(),key=lambda kv:kv[1])
    cap=cap_s if rf=='smooth_additive' else cap_o
    ok=[k for k,v in items if v<=cap]
    return ok[-1] if ok else items[0][0]
def maxd(ds): return max(ds,key=ds.get)
# history dataflip + others select tabular
res=collections.defaultdict(lambda:[0,0,0])
for h in H:
    if h['family']!='synthetic_tabular_classification' or h['task']!='select': continue
